/* Local-only interface styles. No remote fonts, images, or CDN assets. */

/*
 * Warm-dark tokens reconstructed from the reference screenshot as starting
 * values (UX-01). They are approximate calibration targets, not exact
 * Superhuman values; geometry is calibrated on real displays later.
 */
:root {
  color-scheme: dark;
  font-family: var(--font-ui);
  /*
   * Type scale (DESIGN.md "Typography"): one local system sans, a fixed rem
   * scale, two weights. Hierarchy comes from weight (600 vs 400) and tone
   * (Paper White vs Ash), not from extra sizes.
   */
  --font-ui: system-ui, -apple-system, sans-serif;
  --font-mono: ui-monospace, monospace;
  /* 16px: split tabs, context title, contact name, drawer and reader headings. */
  --type-headline: 1rem;
  /* 12px: everything else in the app shell (rows, rail, panes, drawers, reader chrome). */
  --type-body: 0.75rem;
  /* 11px: split-tab counts only. */
  --type-count: 0.6875rem;
  /* Plain-text message bodies in the reader (monospace runs visually larger). */
  --type-mono: 0.85rem;
  --weight-regular: 400;
  --weight-strong: 600;
  --leading-headline: 1.25;
  --leading-ui: 1.35;
  --leading-mono: 1.45;
  --surface: #292826;
  --surface-contact: #1f1e1c;
  --surface-raised: #33312e;
  --focus-fill: #474644;
  --focus-accent: #bba5ed;
  /* DESIGN.md Paper White: 14.7:1 on Warm Charcoal, 9.4:1 on Focus Stone. */
  --text-primary: #ffffff;
  /* DESIGN.md Ash: >=4.5:1 on Focus Stone (4.99:1; the old #a8a29a was 3.73:1). */
  --text-secondary: #c0bcb6;
  /* DESIGN.md Smoke (inactive split tabs, on Warm Charcoal only: 5.4:1) and
     Graphite (resting glyphs). */
  --text-tertiary: #a09c9a;
  --icon-muted: #8e8a87;
  /* DESIGN.md split-header height: content top to the first row. */
  --split-header-height: 78px;
  --unread-marker: #ce9ece;
  --divider: #3b3936;
  --warning: #e4c465;
  --danger: #f1a9a5;
}

* {
  box-sizing: border-box;
}

body {
  margin: 0;
}

button {
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 4px;
  padding: 0.15rem 0.5rem;
  font: inherit;
}

button:focus-visible {
  outline: 2px solid var(--focus-accent);
  outline-offset: 1px;
}

select {
  font: inherit;
}

input,
textarea {
  font: inherit;
  background: var(--surface-raised);
  color: var(--text-primary);
  border: 1px solid var(--divider);
  border-radius: 4px;
}

.app {
  display: flex;
  flex-direction: column;
  height: 100vh;
  background: var(--surface);
  color: var(--text-primary);
}

/* UX-13A: disclosed browser workspaces, deliberately not a native tab strip. */
.fixture-workspaces {
  height: 100vh;
  display: flex;
  flex-direction: column;
  background: var(--surface);
  color: var(--text-primary);
}
.workspace-header {
  padding: 0.4rem 0.75rem;
  border-bottom: 1px solid var(--divider);
  font-size: var(--type-body);
}
.workspace-header p { margin: 0 0 0.35rem; }
.workspace-header nav { display: flex; flex-wrap: wrap; gap: 0.4rem; }
.workspace-header button[aria-current] { background: var(--focus-fill); }
.workspace-panel { flex: 1; min-height: 0; }
.workspace-panel > .app { height: 100%; }

/* Shared: in the accessibility tree, not on screen. */
.visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/*
 * Heading defaults inside the shell (zero specificity, so component classes
 * win): h2 is a Headline, h3/h4 are Title labels. No default 700 weight.
 */
:where(.app-main) h2 {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
}

:where(.app-main) :is(h3, h4) {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  line-height: var(--leading-ui);
}

:where(.app-main) :is(strong, b) {
  font-weight: var(--weight-strong);
}

/*
 * Split header (DESIGN.md "Split Tabs"): one borderless 78px strip in the list
 * column. Hamburger centered 23px into the pane, tabs on the 50px content
 * inset and vertically centered ~42px down, right glyphs on the 32px action
 * pitch with the last glyph centered 32px from the pane edge. Extra rows
 * (split editor, split error) wrap below the tab line.
 */
.app-header {
  display: grid;
  grid-template-columns: 50px minmax(0, 1fr) minmax(0, auto);
  grid-template-rows: minmax(calc(var(--split-header-height) - 6px), auto);
  align-items: center;
  padding: 6px 16px 0 0;
  background: var(--surface);
}

.app-header > .header-row {
  grid-column: 1 / -1;
  padding-left: 50px;
}

.header-alert {
  margin: 0 0 0.5rem;
  font-size: var(--type-body);
  color: var(--danger);
}

/* Ghost glyph button: Graphite at rest, Paper White on hover/focus. */
.header-glyph {
  flex: 0 0 auto;
  display: inline-grid;
  place-items: center;
  width: 32px;
  height: 32px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 4px;
  color: var(--icon-muted);
  cursor: pointer;
}

.header-glyph:hover:not(:disabled),
.header-glyph:focus-visible,
.header-glyph[aria-pressed='true'] {
  color: var(--text-primary);
}

.header-glyph:disabled {
  opacity: 0.45;
  cursor: default;
}

.header-glyph-icon {
  width: 1rem;
  height: 1rem;
}

.header-menu {
  justify-self: start;
  margin-left: 7px;
}

.header-tabs {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
  overflow: hidden;
  /* Room for the focus ring of the first tab inside the clipped line. */
  padding: 4px 4px 4px 0;
  margin: -4px 0;
}

.app-title,
.split-tab {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
}

.app-title {
  margin: 0;
  min-width: 0;
  flex: 0 1 auto;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--text-primary);
}

.app-title-account {
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.split-nav {
  display: flex;
  align-items: baseline;
  gap: 18px;
  min-width: 0;
}

.split-tab {
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 2px;
  color: var(--text-tertiary);
  white-space: nowrap;
  cursor: pointer;
}

.split-tab:hover,
.split-tab[aria-current='page'] {
  color: var(--text-primary);
}

.split-tab:focus-visible {
  outline-offset: 2px;
}

.split-label {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.split-count {
  flex: 0 0 auto;
  font-size: var(--type-count);
  line-height: 1;
  color: var(--text-secondary);
  font-variant-numeric: tabular-nums;
}

/* Active list filter, in words beside the tabs. */
.header-filter {
  flex: 0 0 auto;
  font-size: var(--type-body);
  color: var(--text-secondary);
  white-space: nowrap;
}

.header-trail {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  min-width: 0;
}

/* Compact one-line notes; they give up width before the glyphs do. */
.header-note {
  flex: 0 1 auto;
  min-width: 0;
  margin: 0 12px 0 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

.preview-tag {
  color: var(--warning);
}

.header-link {
  padding: 0 2px;
  background: transparent;
  border: 0;
  color: var(--text-primary);
  font-size: inherit;
  cursor: pointer;
}

.header-link:hover {
  text-decoration: underline;
}

.command-error {
  margin: 0;
  padding: 0.4rem 1rem 0.4rem 50px;
  color: var(--danger);
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
}

.draft-close-recovery {
  border-bottom: 1px solid var(--divider);
  padding: 0.4rem 0.75rem;
  color: var(--warning);
  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
}

.draft-close-recovery p {
  margin: 0;
}

/*
 * Rail + one central list-or-reader surface + contact context. The contact
 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
 * keyboard-operable Contact disclosure instead.
 */
.app-main {
  /* Shell body type: everything not on another step of the scale is 12px. */
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);

  display: flex;
  gap: 0.75rem;
  align-items: center;
  flex-wrap: wrap;
}

.draft-close-recovery p {
  margin: 0;
}

/*
 * Rail + one central list-or-reader surface + contact context. The contact
 * column exists only at >=1000 CSS px; strictly below it, the rail exposes a
 * keyboard-operable Contact disclosure instead.
 */
.app-main {
  /* Shell body type: everything not on another step of the scale is 12px. */
  font-size: var(--type-body);
  line-height: var(--leading-ui);
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  /* Header, in-flow notices, then the list-or-reader surface; the rail and
     contact pane span all three so the header lives in the list column. */
  grid-template-rows: auto auto minmax(0, 1fr);
  flex: 1;
  min-height: 0;
  position: relative;
}

.app-main > .rail {
  grid-column: 1;
  grid-row: 1 / -1;
}

.app-main > .app-header,
.app-main > .list-notices {
  grid-column: 2;
}

.app-main > .app-header { grid-row: 1; }
.app-main > .list-notices { grid-row: 2; min-width: 0; }

.app-main > .central,
.app-main > .account-gate {
  grid-column: 2;
  grid-row: 3;
}

.app-main > .contact-column {
  grid-column: 3;
  grid-row: 1 / -1;
}

@media (min-width: 1000px) {
  .app-main {
    grid-template-columns: auto minmax(0, 1fr) minmax(230px, 280px);
  }
}

.rail {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  padding: 0.5rem 0.4rem;
  border-right: 1px solid var(--divider);
  min-width: 5rem;
}

.rail-item {
  text-align: left;
  background: transparent;
  border-color: transparent;
  color: var(--text-secondary);
  padding: 0.2rem 0.5rem;
  /* Body type in Ash; the current destination steps up to Paper White. */
  font-weight: var(--weight-regular);
}

/* Keep the new local destination from widening the compact browsing rail. */
.rail-done {
  width: 5rem;
  white-space: normal;
}

.rail-item:hover {
  color: var(--text-primary);
}

.rail-item[aria-current='page'],
.rail-item[aria-expanded='true'] {
  color: var(--text-primary);
  background: var(--surface-raised);
  border-color: var(--divider);
}

.rail-spacer {
  flex: 1;
}

.central {
  min-height: 0;
  min-width: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

/* Contact context column. */
.contact-column {
  border-left: 1px solid var(--divider);
  background: var(--surface-contact);
  overflow-y: auto;
  padding: 0.6rem;
  min-height: 0;
}

/* Sentence-case Body caption in Ash: no uppercase tracking (No-Caps-Caption Rule). */
.contact-title {
  font-size: var(--type-body);
  font-weight: var(--weight-regular);
  line-height: var(--leading-ui);
  color: var(--text-secondary);
  margin: 0 0 0.4rem;
}

.contact-identity {
  display: flex;
  flex-direction: column;
  gap: 0.15rem;
  margin: 0;
  overflow-wrap: anywhere;
}

/* Headline: the contact name is the pane's one large line. */
.contact-name {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  line-height: var(--leading-headline);
  color: var(--text-primary);
}

.contact-search {
  background: none;
  border: 0;
  padding: 0;
  text-align: left;
  overflow-wrap: anywhere;
  cursor: pointer;
}
.contact-search:hover { text-decoration: underline; }
.contact-recent { margin-top: 2rem; }
.contact-recent h3 { font-size: var(--type-body); font-weight: var(--weight-strong); color: var(--text-primary); }
.contact-recent ul { list-style: none; padding: 0; }
.contact-recent li { margin: 0.65rem 0; }
.contact-recent button { text-align: left; overflow-wrap: anywhere; }
.mail-search { padding: 1rem; border-bottom: 1px solid var(--divider); }
.mail-search-entry { display: flex; gap: 0.5rem; flex-wrap: wrap; margin: 0.5rem 0; }
.mail-search-entry input { flex: 1 1 16rem; min-width: 0; }
.mail-search p { max-width: 75ch; color: var(--text-secondary); }
/* Title: the email is Paper White semibold (DESIGN.md contact-pane). */
.contact-mailbox {
  color: var(--text-primary);
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
}

.contact-unknown {
  color: var(--text-secondary);
  font-size: var(--type-body);
  margin: 0;
}

/*
 * Utility disclosures overlay the central surface; they are never columns.
 * They start below the split header (positioned against .app-main), so the
 * header's right-hand glyphs (Commands, Search, filters) are never covered
 * by an open drawer.
 */
.utility-drawer {
  position: absolute;
  top: var(--split-header-height);
  right: 0;
  bottom: 0;
  width: min(460px, 92vw);
  background: var(--surface-contact);
  border-left: 1px solid var(--divider);
  box-shadow: -8px 0 24px rgba(0, 0, 0, 0.35);
  overflow-y: auto;
  padding: 0.5rem 0.75rem;
  z-index: 30;
}

.utility-drawer:focus {
  outline: none;
}

.drawer-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.5rem;
  margin-bottom: 0.4rem;
}

.drawer-header h2 {
  font-size: var(--type-headline);
  font-weight: var(--weight-regular);
  margin: 0;
}

/*
 * Compact conversation list (DESIGN.md "Conversation Row"): 36px rows on 12px
 * type in two weights, separated by rhythm alone (no per-row dividers). The
 * row highlight is inset 6px from both pane edges; the 44px left gutter holds
 * the selection checkbox and the read marker, so sender names, date captions
 * and the split tabs share the 50px content inset.
 */
.inbox-scroll {
  list-style: none;
  margin: 0;
  padding: 0;
  cursor: default;
}

.participant:hover,
.participant:focus-visible {
  color: var(--text-primary);
}

/* Contact copy controls: revealed on hover/focus yet always keyboard reachable. */
.contact-copy {
  opacity: 0;
  padding: 0 0.3rem;
  font-size: var(--type-body);
}

.contact-identity:hover .contact-copy,
.contact-identity:focus-within .contact-copy,
.contact-copy:focus-visible {
  opacity: 1;
}

.contact-copy-status {
  margin: 0.3rem 0 0;
  font-size: var(--type-body);
  color: var(--text-secondary);
}

/* Activity (inside its utility disclosure). */
/* In-panel headings are Title labels under the drawer's Headline. */
.activity-title {
  font-size: var(--type-body);
  font-weight: var(--weight-strong);
  margin: 0 0 0.5rem;
}

.activity-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

