  const r = (s) => { const el = document.querySelector(s); if (!el) return null; const b = el.getBoundingClientRect(); return { l: +b.left.toFixed(1), t: +b.top.toFixed(1), w: +b.width.toFixed(1), h: +b.height.toFixed(1), cy: +(b.top + b.height / 2).toFixed(1) }; };
  const cs = (s, p) => { const el = document.querySelector(s); return el ? getComputedStyle(el)[p] : null; };
  return {
    rail: r('.rail'), home: r('.rail-home'), well: r('.rail-well'), firstWell: r('.rail-well .rail-item'), utilities: [...document.querySelectorAll('.rail-utilities .rail-item')].map((b) => { const x = b.getBoundingClientRect(); return [b.dataset.test, +(x.top + x.height / 2).toFixed(1)]; }),
