  if (s === 'w1030') { await load(1030, 800); results[s] = await measure(); await shot('rail-1030.png'); }
  if (s === 'w1280') { await load(1280, 800); results[s] = await measure(); await shot('rail-1280.png'); }
  if (s === 'drawer') {
    await load(1280, 800);
    // Leave an operation pending so the Activity badge shows, then open Activity.
    await js(`document.querySelector('[data-test="rail-activity"]').click()`); await sleep(400);
    results[s] = await measure(); await shot('rail-drawer.png');
  }
  if (s === 'breakpoint') { await load(999, 800); results[s] = await measure(); await shot('rail-breakpoint.png'); }
  if (s === 'focus') {
    await load(1280, 800);
    await js(`document.querySelector('[data-test="rail-done"]').focus({ focusVisible: true })`);
    await cmd('Input.dispatchKeyEvent', { type: 'keyDown', key: 'Tab', code: 'Tab', windowsVirtualKeyCode: 9 });
    await cmd('Input.dispatchKeyEvent', { type: 'keyUp', key: 'Tab', code: 'Tab', windowsVirtualKeyCode: 9 });
    await js(`document.querySelector('[data-test="rail-done"]').focus()`); await sleep(200);
    results[s] = await js('document.activeElement.dataset.test'); await shot('rail-focus.png');
  }
  if (s === 'hovercontact') {
    await load(1280, 800);
    const b = await js(`(() => { const x = document.querySelector('[data-test="contact-name"]').getBoundingClientRect(); return { x: x.left + 10, y: x.top + 5 }; })()`);
    await cmd('Input.dispatchMouseEvent', { type: 'mouseMoved', x: b.x, y: b.y }); await sleep(200);
    await shot('contact-hover.png');
  }
}
console.log(JSON.stringify(results, null, 1));
ws.close(); chrome.kill(); await sleep(300); rmSync(profile, { recursive: true, force: true });

